# write helper cleanly
def outlines(di):
    di=np.array(di); H,W=di.shape; out=di.copy()
    seen=set(); comps=[]
    for i in range(H):
        for j in range(W):
            if di[i,j]==8 and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and di[x,y]==8 and (x,y) not in seen:
                            seen.add((x,y)); q.append((x,y))
                comps.append(cells)
    u=out.copy()
    for c in comps:
        rs=[i for i,_ in c]; cs=[j for _,j in c]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        for j in range(c0,c1+1): u[r0][j]=2; u[r1][j]=2
        for i in range(r0,r1+1): u[i][c0]=2; u[i][c1]=2
    return u
